<?php
namespace Core;require_once __DIR__.'/Guard.php';ml_guard_shield(__FILE__);class RateLimit{private static $dir='';private static $defaults=array('ip'=>array('max'=>120,'window'=>60),'token'=>array('max'=>600,'window'=>60),'user'=>array('max'=>300,'window'=>60),'admin'=>array('max'=>30,'window'=>60),'login'=>array('max'=>10,'window'=>600),'api'=>array('max'=>300,'window'=>60),'search'=>array('max'=>60,'window'=>60),);private static $enabled=true;public static function dir(){if(self::$dir===''){self::$dir=dirname(__DIR__).'/cache/rate';if(!is_dir(self::$dir)){@mkdir(self::$dir,0750,true);}}return self::$dir;}private static function limits(){$a=self::$defaults;try{$b=DB::pdo()->query("SELECT v FROM app_settings WHERE `k`='rate_limits' LIMIT 1")->fetch();if($b&&!empty($b['v'])){$c=json_decode((string)$b['v'],true);if(is_array($c)){foreach($a as $d=>$e){if(isset($c[$d])&&is_array($c[$d])){if(isset($c[$d]['max'])){$a[$d]['max']=(int)$c[$d]['max'];}if(isset($c[$d]['window'])){$a[$d]['window']=(int)$c[$d]['window'];}}}}}}catch(\Throwable $f){}return $a;}public static function check($a,$b='',$c=null,$d=null){if(!self::$enabled){return true;}if($b===''){$b=isset($_SERVER['REMOTE_ADDR'])?(string)$_SERVER['REMOTE_ADDR']:'';}if($b===''){return true;}$e=self::limits();$f=isset($e[$a])?$e[$a]:array('max'=>120,'window'=>60);$g=($c!==null)?(int)$c:(int)$f['max'];$h=($d!==null)?(int)$d:(int)$f['window'];if($g<=0||$h<=0){return true;}$i=self::bucketName($a,$b);$j=self::dir().'/'.$i.'.jsonl';$k=time();$l=$k-$h;$m=@fopen($j,'c');if(!$m){return true;}try{if(!@flock($m,LOCK_EX)){return true;}rewind($m);$n='';while(($o=@fgets($m))!==false){$n.=$o;}$p=(string)$k;$q=array();$r=0;if($n!==''){foreach(explode("\n",$n)as $s){$s=trim($s);if($s===''){continue;}$t=explode('|',$s);if(count($t)<2){continue;}$u=(int)$t[0];if($u<$l){continue;}$v=(int)$t[count($t)-1];$r+=$v;$q[]=$s;}}$r+=1;if($r>$g){$q[]=$p.'|'.$r;ftruncate($m,0);rewind($m);fwrite($m,implode("\n",$q));return false;}$q[]=$p.'|'.$r;ftruncate($m,0);rewind($m);fwrite($m,implode("\n",$q));return true;}finally{@flock($m,LOCK_UN);@fclose($m);}}private static function bucketName($a,$b){return substr(hash('sha256',$a.':'.$b),0,24);}public static function prune($a=3600){$b=self::dir();if(!is_dir($b)){return 0;}$c=time();$d=0;foreach(glob($b.'/*.jsonl')as $e){if($c-@filemtime($e)>$a){@unlink($e);$d++;}}return $d;}}